@Test
public void testHistogramPercentile() {
    analyzer = Analyzer.build("instance_cpu_percentage", null, "instance_cpu_percentage.sum(['le' , 'service' , 'instance']).histogram().histogram_percentile([75,99]).service(['service'], Layer.GENERAL)", meterSystem);
    ImmutableMap<String, SampleFamily> input = ImmutableMap.of("instance_cpu_percentage", SampleFamilyBuilder.newBuilder(Sample.builder().labels(of("le", "0.025", "service", "service1", "instance", "instance1")).value(100).name("instance_cpu_percentage").build(), Sample.builder().labels(of("le", "1.25", "service", "service1", "instance", "instance1")).value(300).name("instance_cpu_percentage").build(), Sample.builder().labels(of("le", "0.75", "service", "service1", "instance", "instance2")).value(122).name("instance_cpu_percentage").build()).build());
    Map<String, AvgHistogramPercentileFunction> actValues = new HashMap<>();
    doAnswer(invocationOnMock -> {
        AvgHistogramPercentileFunction actValue = (AvgHistogramPercentileFunction) invocationOnMock.getArgument(0, AcceptableValue.class);
        if (actValue.getSummation().hasKey("instance1:25")) {
            actValues.put("instance1", actValue);
        } else {
            actValues.put("instance2", actValue);
        }
        return null;
    }).when(meterSystem).doStreamingCalculation(any());
    analyzer.analyse(input);
    Assert.assertEquals(2, actValues.size());
    String expServiceId = IDManager.ServiceID.buildId("service1", true);
    IntList expRanks = new IntList(2) {

        {
            add(75);
            add(99);
        }
    };
    actValues.forEach((key, actValue) -> {
        Assert.assertEquals(expServiceId, actValue.getEntityId());
        Assert.assertThat(expRanks, is(actValue.getRanks()));
    });
    AvgHistogramPercentileFunction instance1 = actValues.get("instance1");
    AvgHistogramPercentileFunction instance2 = actValues.get("instance2");
    Assert.assertEquals(100L, instance1.getSummation().get("instance1:25"), 0.0);
    Assert.assertEquals(300L, instance1.getSummation().get("instance1:1250"), 0.0);
    Assert.assertEquals(1L, instance1.getCount().get("instance1:25"), 0.0);
    Assert.assertEquals(1L, instance1.getCount().get("instance1:1250"), 0.0);
    Assert.assertEquals(122L, instance2.getSummation().get("instance2:750"), 0.0);
    Assert.assertEquals(1L, instance2.getCount().get("instance2:750"), 0.0);
}

