public void testConfigModifyEvent() throws IOException {
    AgentConfigurationsTable agentConfigurationsTable = Whitebox.getInternalState(agentConfigurationsWatcher, "agentConfigurationsTable");
    assertTrue(agentConfigurationsTable.getAgentConfigurationsCache().isEmpty());
    Reader reader = ResourceUtils.read("agent-dynamic-configuration.yml");
    char[] chars = new char[1024 * 1024];
    int length = reader.read(chars);
    agentConfigurationsWatcher.notify(new ConfigChangeWatcher.ConfigChangeEvent(new String(chars, 0, length), ConfigChangeWatcher.EventType.MODIFY));
    AgentConfigurationsTable modifyAgentConfigurationsTable = Whitebox.getInternalState(agentConfigurationsWatcher, "agentConfigurationsTable");
    Map<String, AgentConfigurations> configurationCache = modifyAgentConfigurationsTable.getAgentConfigurationsCache();
    Assert.assertEquals(2, configurationCache.size());
